package com.example.acres.controller; import com.example.acres.dto.AuthDtos.UserResponse; import com.example.acres.service.CurrentUserService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") public class AuthMeController {private final CurrentUserService current;public AuthMeController(CurrentUserService c){current=c;} @GetMapping("/auth/me") public UserResponse me(){var u=current.get();return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.isActive(),u.isMustChangePassword(),u.getLastLoginAt());} @GetMapping("/me") public UserResponse me2(){return me();}}
